135	
136	    public String getAddressLine1() {
137	        return this.addressLine1;
138	    }
139	
140	    public void setAddressLine1(String addressLine1) {
141	        this.addressLine1 = addressLine1;
142	    }
143	
144	    public String getAddressLine2() {
145	        return this.addressLine2;
146	    }
147	
148	    public void setAddressLine2(String addressLine2) {
149	        this.addressLine2 = addressLine2;
