171	
172	    /**
173	     * Stores the email in its canonical lower-cased form so it is always persisted and
174	     * returned lower-cased, regardless of the casing supplied by the client.
175	     */
176	    public void setEmail(String email) {
177	        this.email = email == null ? null : email.toLowerCase(Locale.ROOT);
