179	
180	    public String getPostcode() {
181	        return this.postcode;
182	    }
183	
184	    public void setPostcode(String postcode) {
185	        this.postcode = postcode;
186	    }
187	
188	    public LocalDate getRegistrationDate() {
189	        return this.registrationDate;
190	    }
191	
192	    public void setRegistrationDate(LocalDate registrationDate) {
