239	
240	    /**
241	     * The owner's current primary identifier: presently the {@link #customerCode}. Consumers that
242	     * need "whatever identifies this owner" (such as audit events) read it from here so there is a
243	     * single source of truth; when the customer code is later unified into the member id, only this
244	     * method changes and every consumer follows.
245	     */
246	    @Transient
247	    public String getPrimaryIdentifier() {
248	        return this.customerCode;
249	    }
250	
251	    public String getHouseholdId() {
