256	        this.householdId = householdId;
257	    }
258	
259	    public Integer getNamesakeCount() {
260	        return this.namesakeCount;
261	    }
262	
263	    public void setNamesakeCount(Integer namesakeCount) {
264	        this.namesakeCount = namesakeCount;
265	    }
266	
267	    public Integer getHouseholdSize() {
268	        return this.householdSize;
269	    }
270	
271	    public void setHouseholdSize(Integer householdSize) {
272	        this.householdSize = householdSize;
273	    }
274	
