281	        return this.membershipLevel;
282	    }
283	
284	    public void setMembershipLevel(Integer membershipLevel) {
285	        this.membershipLevel = membershipLevel;
286	    }
287	
288	    public boolean isBulkSignupWarning() {
289	        return this.bulkSignupWarning;
290	    }
291	
292	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
293	        this.bulkSignupWarning = bulkSignupWarning;
294	    }
295	
296	    public boolean isCapacityWarning() {
297	        return this.capacityWarning;
298	    }
299	
300	    public void setCapacityWarning(boolean capacityWarning) {
301	        this.capacityWarning = capacityWarning;
302	    }
303	
304	    public boolean isPossibleDuplicate() {
305	        return this.possibleDuplicate;
306	    }
307	
308	    public void setPossibleDuplicate(boolean possibleDuplicate) {
309	        this.possibleDuplicate = possibleDuplicate;
310	    }
311	
312	    public Integer getPossibleDuplicateOf() {
313	        return this.possibleDuplicateOf;
314	    }
315	
316	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
317	        this.possibleDuplicateOf = possibleDuplicateOf;
318	    }
319	
320	    /**
321	     * Whether this owner has been soft-deleted: the record is retained but flagged so it is
322	     * excluded from the create endpoint's duplicate and identity checks. A newly created owner
323	     * is not deleted.
324	     */
325	    public boolean isDeleted() {
326	        return this.deleted;
327	    }
328	
329	    public void setDeleted(boolean deleted) {
330	        this.deleted = deleted;
331	    }
332	
333	    /**
334	     * The derived key that uniquely identifies an owner for duplicate detection: the SHA-256 hex of
335	     * the normalized telephone, the (lower-cased) email or the empty string when absent, and the
336	     * {@linkplain Soundex Soundex} code of the last name, joined with {@code '|'}. Two owners are
337	     * duplicates only when their whole identity keys are equal, so owners sharing a last name (or a
338	     * similar-sounding one) and postcode but carrying different telephones remain distinct.
339	     */
340	    @Transient
341	    public String getIdentityKey() {
342	        return Sha256.hex(this.telephone + "|"
343	            + (this.email == null ? "" : this.email) + "|"
344	            + Soundex.encode(this.lastName));
345	    }
346	
347	    /**
348	     * On first persist, default the registration date to the server's current date when the
349	     * client did not supply one, then roll the effective date forward so it always falls on a
350	     * business day (a weekend moves to the following Monday).
351	     */
352	    @PrePersist
353	    private void defaultRegistrationDate() {
354	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
355	        this.registrationDate = BusinessDay.rollForward(effectiveDate);
356	    }
357	
358	    protected Set<Pet> getPetsInternal() {
359	        if (this.pets == null) {
360	            this.pets = new HashSet<>();
361	        }
362	        return this.pets;
363	    }
364	
365	    protected void setPetsInternal(Set<Pet> pets) {
366	        this.pets = pets;
367	    }
368	
369	    public List<Pet> getPets() {
370	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
371	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
372	        return Collections.unmodifiableList(sortedPets);
373	    }
374	
375	    public void setPets(List<Pet> pets) {
376	        this.pets = new HashSet<>(pets);
377	    }
378	
379	    public void addPet(Pet pet) {
380	        getPetsInternal().add(pet);
381	        pet.setOwner(this);
382	    }
383	
384	    /**
385	     * Return the Pet with the given name, or null if none found for this Owner.
386	     *
387	     * @param name to test
388	     * @return true if pet name is already in use
389	     */
390	    public Pet getPet(String name) {
391	        return getPet(name, false);
392	    }
393	
394	    /**
395	     * Return the Pet with the given name, or null if none found for this Owner.
396	     *
397	     * @param name to test
398	     * @return true if pet name is already in use
399	     */
400	    public Pet getPet(String name, boolean ignoreNew) {
401	        name = name.toLowerCase();
402	        for (Pet pet : getPetsInternal()) {
403	            if (!ignoreNew || !pet.isNew()) {
404	                String compName = pet.getName();
405	                compName = compName.toLowerCase();
406	                if (compName.equals(name)) {
407	                    return pet;
408	                }
409	            }
410	        }
411	        return null;
412	    }
413	
414	    public Pet getPet(Integer petId) {
415	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
416	    }
417	
418	    @Override
419	    public String toString() {
420	        return new ToStringCreator(this)
421	
422	            .append("id", this.getId())
423	            .append("new", this.isNew())
424	            .append("lastName", this.getLastName())
425	            .append("firstName", this.getFirstName())
426	            .append("address", this.address)
427	            .append("city", this.city)
428	            .append("telephone", this.telephone)
429	            .append("email", this.email)
430	            .toString();
431	    }
432	}
