1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.mapstruct.Named;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
13	import org.springframework.samples.petclinic.rest.validation.LocalityResolver;
14	import org.springframework.samples.petclinic.rest.validation.TelephoneFormatter;
15	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
16	import org.springframework.samples.petclinic.rest.validation.TimezoneResolver;
17	import org.springframework.samples.petclinic.util.Luhn;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public interface OwnerMapper {
27	
28	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
29	    @Mapping(target = "telephoneDisplay", expression = "java(formatTelephoneDisplay(owner))")
30	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
31	    @Mapping(target = "locality", expression = "java(resolveLocality(owner))")
32	    @Mapping(target = "timezone", expression = "java(resolveTimezone(owner))")
33	    @Mapping(target = "fiscalYear", expression = "java(owner.getFiscalYear())")
34	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
35	    @Mapping(target = "checkDigit", expression = "java(computeCheckDigit(owner))")
36	    @Mapping(target = "membershipPoints", expression = "java(resolveMembershipPoints(owner))")
37	    @Mapping(target = "membershipLevel", expression = "java(resolveMembershipLevel(owner))")
38	    @Mapping(target = "contactPreference", expression = "java(resolveContactPreference(owner))")
39	    @Mapping(target = "ageBand", expression = "java(resolveAgeBand(owner))")
40	    @Mapping(target = "ownerSegment", expression = "java(resolveOwnerSegment(owner))")
41	    @Mapping(target = "identityKey", expression = "java(owner.getIdentityKey())")
42	    @Mapping(target = "salutation", expression = "java(owner.getSalutation())")
43	    @Mapping(target = "selfLink", expression = "java(formatSelfLink(owner))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    Owner toOwner(OwnerDto ownerDto);
47	
48	    /**
49	     * Formats the owner's canonical API self link as {@code "/api/owners/<id>"}.
50	     */
51	    default String formatSelfLink(Owner owner) {
52	        return "/api/owners/" + owner.getId();
53	    }
54	
55	    /**
56	     * Formats the owner's stored names for display as {@code "LastName, FirstName"}.
57	     */
58	    default String formatDisplayName(Owner owner) {
59	        return owner.getLastName() + ", " + owner.getFirstName();
60	    }
61	
62	    /**
63	     * Formats the owner's stored E.164 telephone for human display (country code, a space and the
64	     * national digits grouped in threes), leaving the raw {@code telephone} in E.164 form.
65	     */
66	    default String formatTelephoneDisplay(Owner owner) {
67	        return TelephoneFormatter.toDisplay(owner.getTelephone());
68	    }
69	
70	    /**
71	     * Formats the owner's initials as the upper-cased first letters of firstName and
72	     * lastName, dot-separated with a trailing dot, e.g. {@code "J.S."}.
73	     */
74	    default String formatInitials(Owner owner) {
75	        return initial(owner.getFirstName()) + initial(owner.getLastName());
76	    }
77	
78	    /** The upper-cased first letter of {@code name} followed by a dot. */
79	    private String initial(String name) {
80	        return Character.toUpperCase(name.charAt(0)) + ".";
81	    }
82	
83	    /**
84	     * Derives the owner's locality (canonical region) from the leading {@code <REGION>} segment of
85	     * its {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality always agrees with the
86	     * region encoded in the owner's identity.
87	     */
88	    default String resolveLocality(Owner owner) {
89	        String customerCode = owner.getCustomerCode();
90	        return customerCode.substring(0, customerCode.indexOf('-'));
91	    }
92	
93	    /**
94	     * Derives the owner's IANA timezone from its {@linkplain #resolveLocality(Owner) locality}
95	     * (canonical region) via the fixed region-to-timezone table, or {@code null} when the locality
96	     * has no known timezone.
97	     */
98	    default String resolveTimezone(Owner owner) {
99	        return TimezoneResolver.resolve(resolveLocality(owner));
100	    }
101	
102	    /**
103	     * Formats the owner's membership number as {@code "<customerCode>-M<YY>"}, where YY is the
104	     * last two digits of the {@linkplain Owner#getFiscalYear() fiscal year} of the registration
105	     * date, e.g. {@code "LON-SMI-0007-M26"}.
106	     */
107	    default String formatMembershipNumber(Owner owner) {
108	        return owner.getCustomerCode() + "-M" + owner.getFiscalYear().substring(2);
109	    }
110	
111	    /**
112	     * Computes the Luhn check digit over the decimal digits of the owner's customer code.
113	     */
114	    default Integer computeCheckDigit(Owner owner) {
115	        return Luhn.checkDigit(owner.getCustomerCode());
116	    }
117	
118	    /** The minimum tenure, in fiscal years, an owner must exceed to earn the tenure membership points. */
119	    int TENURE_POINTS_THRESHOLD_FISCAL_YEARS = 1;
120	
121	    /** The minimum household size that earns the household membership points. */
122	    int HOUSEHOLD_POINTS_THRESHOLD = 3;
123	
124	    /**
125	     * Resolves the owner's membership points: starts at {@code 0}, plus {@code 2} when an email is
126	     * present, plus {@code 1} when the owner has no namesakes (namesakeCount is 0), plus {@code 2}
127	     * when the owner belongs to a household of {@value #HOUSEHOLD_POINTS_THRESHOLD} or more, plus
128	     * {@code 3} when the owner's tenure exceeds {@value #TENURE_POINTS_THRESHOLD_FISCAL_YEARS} fiscal year.
129	     */
130	    default Integer resolveMembershipPoints(Owner owner) {
131	        int points = 0;
132	        if (hasEmail(owner)) {
133	            points += 2;
134	        }
135	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
136	            points += 1;
137	        }
138	        Integer householdSize = owner.getHouseholdSize();
139	        if (householdSize != null && householdSize >= HOUSEHOLD_POINTS_THRESHOLD) {
140	            points += 2;
141	        }
142	        if (owner.getTenureFiscalYears() > TENURE_POINTS_THRESHOLD_FISCAL_YEARS) {
143	            points += 3;
144	        }
145	        return points;
146	    }
147	
148	    /**
149	     * Resolves the owner's effective membership level: the level persisted (capped) on creation when
150	     * present, otherwise the level {@linkplain #deriveMembershipLevel derived} from its membership
151	     * points.
152	     */
153	    default Integer resolveMembershipLevel(Owner owner) {
154	        Integer stored = owner.getMembershipLevel();
155	        return stored != null ? stored : deriveMembershipLevel(owner);
156	    }
157	
158	    /**
159	     * Derives the owner's numeric membership level from its {@linkplain #resolveMembershipPoints
160	     * membership points}: level {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
161	     * {@code 3} for {@code 4-5} and {@code 4} for {@code 6} or more.
162	     */
163	    default Integer deriveMembershipLevel(Owner owner) {
164	        int points = resolveMembershipPoints(owner);
165	        if (points <= 1) {
166	            return 1;
167	        }
168	        if (points <= 3) {
169	            return 2;
170	        }
171	        if (points <= 5) {
172	            return 3;
173	        }
174	        return 4;
175	    }
176	
177	    /** The minimum membership level that qualifies an owner for the {@code PREMIUM} tier. */
178	    int PREMIUM_TIER_MIN_LEVEL = 3;
179	
180	    /**
181	     * Resolves the owner's segment, formatted {@code "<TIER>_<AREA>"}. TIER is {@code "PREMIUM"} when
182	     * the owner's {@linkplain #resolveMembershipLevel membership level} is at least
183	     * {@value #PREMIUM_TIER_MIN_LEVEL}, otherwise {@code "STANDARD"}. AREA is {@code "METRO"} when the
184	     * owner's {@linkplain #resolveLocality locality} is a known region, otherwise {@code "REGIONAL"}.
185	     */
186	    default String resolveOwnerSegment(Owner owner) {
187	        String tier = resolveMembershipLevel(owner) >= PREMIUM_TIER_MIN_LEVEL ? "PREMIUM" : "STANDARD";
188	        String area = LocalityResolver.isKnownRegion(resolveLocality(owner)) ? "METRO" : "REGIONAL";
189	        return tier + "_" + area;
190	    }
191	
192	    /**
193	     * Resolves the owner's preferred contact channel: {@code "EMAIL"} when an email is
194	     * present, otherwise {@code "PHONE"}.
195	     */
196	    default String resolveContactPreference(Owner owner) {
197	        return hasEmail(owner) ? "EMAIL" : "PHONE";
198	    }
199	
200	    /** Whether the owner has a non-blank email address. */
201	    private boolean hasEmail(Owner owner) {
202	        return owner.getEmail() != null && !owner.getEmail().isBlank();
203	    }
204	
205	    /**
206	     * Resolves the owner's age band (as a string) from its birth date against its registration
207	     * date, or {@code null} when the owner has no birth date.
208	     */
209	    default String resolveAgeBand(Owner owner) {
210	        return owner.getAgeBand() == null ? null : owner.getAgeBand().name();
211	    }
212	
213	    @Mapping(target = "id", ignore = true)
214	    @Mapping(target = "pets", ignore = true)
215	    @Mapping(target = "householdId", ignore = true)
216	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
217	    @Mapping(target = "addressLine1", source = "addressLine1", qualifiedByName = "normalizeAddress")
218	    @Mapping(target = "addressLine2", source = "addressLine2", qualifiedByName = "normalizeAddress")
219	    @Mapping(target = "address", expression = "java(composeAddress(ownerDto))")
220	    Owner toOwner(OwnerFieldsDto ownerDto);
221	
222	    /**
223	     * Store the address in its canonical form (trimmed, whitespace-collapsed, upper-cased and with
224	     * common abbreviations expanded), so it is always persisted, returned and compared normalized.
225	     */
226	    @Named("normalizeAddress")
227	    default String normalizeAddress(String address) {
228	        return AddressNormalizer.normalize(address);
229	    }
230	
231	    /**
232	     * Compose the owner's canonical {@code address} from the supplied fields, preferring the
233	     * structured form: when {@code addressLine1} is present it is the normalized {@code addressLine1}
234	     * with a single space and the normalized {@code addressLine2} appended when that line is present;
235	     * otherwise it falls back to the normalized flat {@code address}. Composing into the single
236	     * {@code address} field keeps everything that reads the address (household hash, postcode
237	     * validation, locality) consistent whichever form was supplied.
238	     */
239	    default String composeAddress(OwnerFieldsDto ownerDto) {
240	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
241	        if (line1 == null || line1.isBlank()) {
242	            return normalizeAddress(ownerDto.getAddress());
243	        }
244	        String line2 = normalizeAddress(ownerDto.getAddressLine2());
245	        return (line2 == null || line2.isBlank()) ? line1 : line1 + " " + line2;
246	    }
247	
248	    /**
249	     * Store the telephone in E.164 form. Validation ({@code @Telephone}) has already guaranteed
250	     * the raw value normalizes to a valid E.164 number.
251	     */
252	    @Named("normalizeTelephone")
253	    default String normalizeTelephone(String telephone) {
254	        return TelephoneNormalizer.toE164(telephone);
255	    }
256	
257	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
258	
259	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
260	
261	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
262	        OwnerPageDto ownerPageDto = new OwnerPageDto();
